#include<iostream>
            #include<vector>
            using namespace std;
            int main(){
                int n;
                cin>>n;
                vector<int> nums(n);
                for(int i=0;i<n;i++){
                    cin>>nums[i];
                }
                int total=0;
                for(int i=0;i<n;i++){
                    total+=nums[i];
                }
                int left=0;
                for(int i=0;i<n;i++){
                    int right=total-left-nums[i];
                    if(left==right){
                        cout<<i;
                        return 0;
                    }
                    left+=nums[i];
                }
                cout<<-1;    
                return 0;
            }
